-- audit-service PostgreSQL V001 — 与 mysql/V001__init.sql **版本号与表结构对齐**。
--
-- 转换规则（设计文档 §3 方言差异归属表）：
--   DATETIME / DATETIME(3)  -> TIMESTAMPTZ / TIMESTAMPTZ(3)  （§3 #3；**不是** TIMESTAMP）
--   TINYINT(1)              -> BOOLEAN                        （§3 #12）
--   JSON                    -> JSON 原样                       （§3 #5；PG 原生支持）
--   AUTO_INCREMENT          -> GENERATED BY DEFAULT AS IDENTITY（§3 #13）
--   列内联 COMMENT           -> 删除                            （§3 #14）
--   内联 INDEX / UNIQUE KEY  -> 独立 CREATE INDEX              （§3 #15/#16）
--   ENGINE / CHARSET / COLLATE -> 删除                          （§3 #17）
--   CURRENT_TIMESTAMP(3)    -> 原样保留                          （§3 #4；PG 16 接受）
--
-- ⚠️ 关于 IDENTITY 用 BY DEFAULT 而非 ALWAYS：
--   MySQL 的 AUTO_INCREMENT **允许**显式插入 id 值，而 `GENERATED ALWAYS` 会拒绝
--   （必须 OVERRIDING SYSTEM VALUE）。要忠实保持 MySQL 语义（测试 fixture 里
--   常显式指定 id），必须用 `GENERATED BY DEFAULT AS IDENTITY`。
--
-- ⚠️ 关于 `path(255)` 前缀索引：
--   MySQL 写了 `INDEX ... (path(255))`（前缀索引），PG **不支持**前缀索引，
--   这里建整列索引。语义更宽（覆盖任意长度），代价是索引略大；查询模式不受影响。
--
-- ⚠️ 迁移执行器是「先按 ASCII 分号切分、再剥离 `--` 注释行」，
--   因此注释里不得出现 ASCII 分号（本文件已避免）。

CREATE TABLE audit_operation_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id VARCHAR(64) NOT NULL,
    action VARCHAR(128) NOT NULL,
    resource VARCHAR(256) NOT NULL,
    resource_id VARCHAR(128),
    before_value TEXT,
    after_value TEXT,
    request_id VARCHAR(64) NOT NULL,
    ip_address VARCHAR(45),
    user_agent TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_audit_operation_logs_user_id ON audit_operation_logs (user_id);

CREATE INDEX idx_audit_operation_logs_action ON audit_operation_logs (action);

CREATE INDEX idx_audit_operation_logs_created_at ON audit_operation_logs (created_at);

CREATE TABLE audit_login_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id VARCHAR(64),
    username VARCHAR(128) NOT NULL,
    success BOOLEAN NOT NULL,
    fail_reason VARCHAR(256),
    ip_address VARCHAR(45) NOT NULL,
    location VARCHAR(256),
    user_agent TEXT,
    request_id VARCHAR(64) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_audit_login_logs_username ON audit_login_logs (username);

CREATE INDEX idx_audit_login_logs_success ON audit_login_logs (success);

CREATE INDEX idx_audit_login_logs_created_at ON audit_login_logs (created_at);

CREATE TABLE audit_api_access_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_name VARCHAR(64) NOT NULL,
    method VARCHAR(10) NOT NULL,
    path VARCHAR(512) NOT NULL,
    status_code INT NOT NULL,
    duration_ms INT NOT NULL,
    user_id VARCHAR(64),
    request_id VARCHAR(64) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_audit_api_access_logs_service_name ON audit_api_access_logs (service_name);

CREATE INDEX idx_audit_api_access_logs_path ON audit_api_access_logs (path);

CREATE INDEX idx_audit_api_access_logs_created_at ON audit_api_access_logs (created_at);

CREATE TABLE IF NOT EXISTS audit_events (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_id CHAR(36) NOT NULL,
    event_type VARCHAR(128) NOT NULL,
    occurred_at TIMESTAMPTZ(3) NOT NULL,
    received_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    trace_id VARCHAR(64),
    producer VARCHAR(64) NOT NULL,
    payload_json JSON NOT NULL
);

CREATE UNIQUE INDEX uk_audit_events_event_id ON audit_events (event_id);

CREATE INDEX idx_audit_events_type_time ON audit_events (event_type, occurred_at);
